11	/// Maximum JSON payload accepted from stdin via the `-` sentinel. 32 MiB is
12	/// well above any realistic review-ledger / flow-context apply-ops payload
13	/// (typical is < 64 KiB) while being small enough to fail fast if a caller
14	/// accidentally pipes a log or a binary into `--json -`.
15	const MAX_STDIN_BYTES: u64 = 32 * 1024 * 1024;
16	
17	/// Resolve a JSON argument: if it's literally "-", read stdin to a String.
18	/// Otherwise return the argument as-is.
19	///
20	/// Stdin handling (R7):
21	/// - Refuses to block on an interactive TTY — a user piping nothing into `--json -`
22	///   would otherwise hang forever with no prompt or feedback.
23	/// - Caps the read at `MAX_STDIN_BYTES`; an oversize payload is truncated on
24	///   the input side so a misrouted log doesn't balloon tomlctl's heap.
25	fn read_json_arg(arg: &str) -> Result<String> {
26	    if arg == "-" {
27	        if std::io::stdin().is_terminal() {
28	            bail!(
29	                "stdin is a TTY — pipe JSON (e.g. `cat payload.json | tomlctl … --json -`) or pass `--json '<literal>'`"
30	            );
31	        }
32	        let mut buf = String::new();
33	        std::io::stdin()
34	            .lock()
35	            .take(MAX_STDIN_BYTES)
36	            .read_to_string(&mut buf)
37	            .context("reading JSON from stdin")?;
38	        if buf.trim().is_empty() {
39	            bail!("stdin was empty — expected JSON payload");
40	        }
41	        Ok(buf)
42	    } else {
43	        Ok(arg.to_string())
44	    }
45	}
