47	#[derive(Parser)]
48	#[command(
49	    name = "tomlctl",
50	    version,
51	    about = "Read and write TOML files used by Claude Code flows and ledgers"
52	)]
53	struct Cli {
54	    /// Allow write operations on files outside the current repo's `.claude/` directory.
55	    /// By default, writes are refused if the canonical target path is not under
56	    /// `<git-top-level>/.claude/` (or the CWD, if not in a git repo). Use this to
57	    /// intentionally edit a flow file in another location.
58	    #[arg(long = "allow-outside", global = true)]
59	    allow_outside: bool,
60	
61	    /// Suppress writing the `<file>.sha256` integrity sidecar. Default behaviour
62	    /// is to write a sidecar alongside every TOML write (standard `sha256sum`
63	    /// format: `<hex>  <basename>\n`). Pass this flag to opt out, e.g. when the
64	    /// target filesystem does not tolerate an extra sidecar file.
65	    #[arg(long = "no-write-integrity", global = true)]
66	    no_write_integrity: bool,
67	
68	    /// Before any read operation, verify the target file against its
69	    /// `<file>.sha256` sidecar. Errors if the sidecar is missing or the
70	    /// digest disagrees. Never auto-repairs.
71	    #[arg(long = "verify-integrity", global = true)]
72	    verify_integrity: bool,
73	
74	    /// Treat an integrity-sidecar write failure as a hard error instead of a
75	    /// stderr warning. Off by default — the primary data is already durable
76	    /// on disk by the time the sidecar is attempted, so a failed sidecar is
77	    /// usually recoverable by re-running the write. Pass this flag on a
78	    /// tight-integrity path (e.g. signed-artifact builds) where a missing or
79	    /// stale sidecar must fail CI.
80	    #[arg(long = "strict-integrity", global = true)]
81	    strict_integrity: bool,
82	
83	    #[command(subcommand)]
84	    cmd: Cmd,
85	}
