212	#[derive(Subcommand)]
213	enum BlocksOp {
214	    /// Verify one or more named shared-blocks are byte-identical across files.
215	    ///
216	    /// Each `<marker-name>` is scanned for the HTML-comment pair:
217	    ///   `<!-- SHARED-BLOCK:<marker-name> START -->` … `<!-- SHARED-BLOCK:<marker-name> END -->`
218	    /// The hash is taken over the byte-content strictly between the markers
219	    /// (each line joined by `\n`, matching `awk '{print}' | sha256sum`).
220	    Verify {
221	        /// Files to check.
222	        files: Vec<PathBuf>,
223	        /// Block name(s) to verify. If omitted, the union of block names
224	        /// present in the first listed file is used.
225	        #[arg(long = "block")]
226	        block: Vec<String>,
