247	/// Pair of integrity-sidecar-related global flags, bundled to shorten call
248	/// signatures for read paths.
249	#[derive(Clone, Copy)]
250	struct IntegrityOpts {
251	    write_sidecar: bool,
252	    verify_on_read: bool,
253	    /// When true, a sidecar-write failure becomes a hard error. When false
254	    /// (default), the failure is logged to stderr and the outer operation
255	    /// still succeeds — the primary TOML data has already been atomically
256	    /// persisted at that point.
257	    strict: bool,
258	}
259	
260	impl IntegrityOpts {
261	    fn from_cli(cli: &Cli) -> Self {
262	        Self {
263	            write_sidecar: !cli.no_write_integrity,
264	            verify_on_read: cli.verify_integrity,
265	            strict: cli.strict_integrity,
266	        }
267	    }
268	}
