270	fn main() {
271	    if let Err(err) = run() {
272	        // R16: `{:#}` prints the full anyhow cause chain inline; combined with
273	        // `with_context(…"parsing {}", path)` in `read_toml`, toml's Display
274	        // impl then emits line:col + caret diagnostics for syntax errors.
275	        eprintln!("tomlctl: {:#}", err);
276	        std::process::exit(1);
277	    }
278	}
