280	fn run() -> Result<()> {
281	    let cli = Cli::parse();
282	    let allow_outside = cli.allow_outside;
283	    let integrity = IntegrityOpts::from_cli(&cli);
284	    match cli.cmd {
285	        Cmd::Parse { file } => {
286	            maybe_verify_integrity(&file, integrity)?;
287	            let doc = read_toml(&file)?;
288	            print_json(&toml_to_json(&doc))?;
289	        }
290	        Cmd::Get { file, path } => {
291	            maybe_verify_integrity(&file, integrity)?;
292	            let doc = read_toml(&file)?;
293	            let out = match path.as_deref() {
294	                None | Some("") => toml_to_json(&doc),
295	                Some(p) => toml_to_json(
296	                    navigate(&doc, p).ok_or_else(|| anyhow!("key path `{}` not found", p))?,
297	                ),
298	            };
299	            print_json(&out)?;
300	        }
301	        Cmd::Set {
302	            file,
303	            path,
304	            value,
305	            ty,
306	        } => {
307	            mutate_doc(&file, allow_outside, integrity, |doc| {
308	                let v = parse_scalar(&value, ty)?;
309	                set_at_path(doc, &path, v)
310	            })?;
311	            println!("{{\"ok\":true}}");
312	        }
313	        Cmd::SetJson { file, path, json } => {
314	            let json = read_json_arg(&json)?;
315	            mutate_doc(&file, allow_outside, integrity, |doc| {
316	                let parsed: JsonValue = serde_json::from_str(&json).context("parsing --json")?;
317	                let last_key = path.rsplit_once('.').map(|(_, k)| k).unwrap_or(path.as_str());
318	                let v = maybe_date_coerce(last_key, &parsed)?;
319	                set_at_path(doc, &path, v)
320	            })?;
321	            println!("{{\"ok\":true}}");
322	        }
323	        Cmd::Validate { file } => {
324	            maybe_verify_integrity(&file, integrity)?;
325	            read_toml(&file)?;
326	            println!("{{\"ok\":true}}");
327	        }
328	        Cmd::Items { op } => items_dispatch(op, allow_outside, integrity)?,
329	        Cmd::Blocks { op } => blocks_dispatch(op)?,
330	    }
331	    Ok(())
332	}
