334	fn items_dispatch(op: ItemsOp, allow_outside: bool, integrity: IntegrityOpts) -> Result<()> {
335	    match op {
336	        ItemsOp::List {
337	            file,
338	            status,
339	            category,
340	            newer_than,
341	            file_filter,
342	            count,
343	        } => {
344	            maybe_verify_integrity(&file, integrity)?;
345	            let doc = read_toml(&file)?;
346	            let newer_than_dt = match newer_than.as_deref() {
347	                Some(s) => Some(
348	                    s.parse::<toml::value::Datetime>()
349	                        .with_context(|| format!("--newer-than `{}` is not a valid ISO date", s))?,
350	                ),
351	                None => None,
352	            };
353	            let filters = ListFilters {
354	                status: status.as_deref(),
355	                category: category.as_deref(),
356	                newer_than: newer_than_dt.as_ref(),
357	                file_filter: file_filter.as_deref(),
358	            };
359	            let list = items_list(&doc, filters)?;
360	            if count {
361	                let mut obj = serde_json::Map::new();
362	                obj.insert("count".into(), JsonValue::from(list.len()));
363	                print_json(&JsonValue::Object(obj))?;
364	            } else {
365	                print_json(&JsonValue::Array(list))?;
366	            }
367	        }
368	        ItemsOp::Get { file, id } => {
369	            maybe_verify_integrity(&file, integrity)?;
370	            let doc = read_toml(&file)?;
371	            print_json(&items_get(&doc, &id)?)?;
372	        }
373	        ItemsOp::Add { file, json } => {
374	            let json = read_json_arg(&json)?;
375	            mutate_doc(&file, allow_outside, integrity, |doc| items_add(doc, &json))?;
376	            println!("{{\"ok\":true}}");
377	        }
378	        ItemsOp::Update {
379	            file,
380	            id,
381	            json,
382	            unset,
383	        } => {
384	            let json = read_json_arg(&json)?;
385	            mutate_doc(&file, allow_outside, integrity, |doc| {
386	                items_update(doc, &id, &json, &unset)
387	            })?;
388	            println!("{{\"ok\":true}}");
389	        }
390	        ItemsOp::Remove { file, id } => {
391	            mutate_doc(&file, allow_outside, integrity, |doc| items_remove(doc, &id))?;
392	            println!("{{\"ok\":true}}");
393	        }
394	        ItemsOp::Apply { file, ops, array } => {
395	            let ops = read_json_arg(&ops)?;
396	            mutate_doc(&file, allow_outside, integrity, |doc| {
397	                items_apply_to(doc, &ops, &array)
398	            })?;
399	            println!("{{\"ok\":true}}");
400	        }

400	        }
401	        ItemsOp::NextId { file, prefix } => {
402	            // R19: if the target ledger doesn't exist yet, there's nothing to
403	            // parse or verify — the "next" id is trivially `<prefix>1`. This
404	            // lets flows call `items next-id` before the ledger is initialised
405	            // (e.g. during bootstrap of a new flow directory).
406	            if !file.exists() {
407	                if prefix.is_empty() {
408	                    bail!("prefix must not be empty — use a letter like R, O, or A");
409	                }
410	                if prefix.chars().all(|c| c.is_ascii_digit()) {
411	                    bail!("prefix must not be all-digit — would collide with numeric-suffix parsing");
412	                }
413	                println!("{}", serde_json::to_string(&format!("{}1", prefix))?);
414	            } else {
415	                maybe_verify_integrity(&file, integrity)?;
416	                let doc = read_toml(&file)?;
417	                let id = items_next_id(&doc, &prefix)?;
418	                println!("{}", serde_json::to_string(&id)?);
419	            }
420	        }
421	        ItemsOp::FindDuplicates { file, tier } => {
422	            maybe_verify_integrity(&file, integrity)?;
423	            let doc = read_toml(&file)?;
424	            let groups = items_find_duplicates(&doc, tier)?;
425	            print_json(&JsonValue::Array(groups))?;
426	        }
427	        ItemsOp::Orphans { file } => {
428	            maybe_verify_integrity(&file, integrity)?;
429	            let doc = read_toml(&file)?;
430	            let orphans = items_orphans(&doc)?;
431	            print_json(&JsonValue::Array(orphans))?;
432	        }
433	    }
434	    Ok(())
435	}
