450	fn read_toml(path: &Path) -> Result<TomlValue> {
451	    let s = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
452	    toml::from_str::<TomlValue>(&s).with_context(|| format!("parsing {}", path.display()))
453	}
