455	/// Run a closure that mutates a TOML document at `file` under the standard
456	/// write pipeline: `guard_write_path` → `with_exclusive_lock` → `read_toml` →
457	/// `f(&mut doc)` → `write_toml_with_sidecar`. Centralises what was previously
458	/// open-coded at each `Cmd::{Set,SetJson}` / `ItemsOp::{Add,Update,Remove,Apply}`
459	/// dispatch site.
460	fn mutate_doc<F>(
461	    file: &Path,
462	    allow_outside: bool,
463	    integrity: IntegrityOpts,
464	    f: F,
465	) -> Result<()>
466	where
467	    F: FnOnce(&mut TomlValue) -> Result<()>,
468	{
469	    guard_write_path(file, allow_outside)?;
470	    with_exclusive_lock(file, || {
471	        let mut doc = read_toml(file)?;
472	        f(&mut doc)?;
473	        // R3 TOCTOU narrowing: re-canonicalise target parent immediately before
474	        // the atomic persist and re-check that it still lies under `.claude/`.
475	        // Only enforced when `--allow-outside` was NOT set, since an explicit
476	        // opt-out was granted by the user in that case. This narrows (but does
477	        // not close) the window between `guard_write_path()` and `persist()`;
478	        // closing it fully requires O_NOFOLLOW via nix/rustix.
479	        if !allow_outside {
480	            recheck_claude_containment(file)?;
481	        }
482	        write_toml_with_sidecar(file, &doc, integrity)?;
483	        Ok(())
484	    })
485	}
486	
487	/// Re-canonicalise `file`'s parent and assert it still starts with the
488	/// `.claude/` canonical root. Used by `mutate_doc` to narrow the TOCTOU window
489	/// described in R3.
490	fn recheck_claude_containment(file: &Path) -> Result<()> {
491	    let parent = file
492	        .parent()
493	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
494	        .unwrap_or(Path::new("."));
495	    let parent_canonical = parent
496	        .canonicalize()
497	        .with_context(|| format!("re-canonicalising parent of {} before persist", file.display()))?;
498	    let root = repo_or_cwd_root()?;
499	    let claude_dir = root.join(".claude");
500	    let claude_canonical = claude_dir.canonicalize().unwrap_or(claude_dir);
501	    if parent_canonical.starts_with(&claude_canonical) {
502	        return Ok(());
503	    }
504	    bail!(
505	        "pre-persist containment check failed: target parent {} is no longer under {} (possible TOCTOU symlink swap since guard_write_path — aborting)",
506	        parent_canonical.display(),
507	        claude_canonical.display()
508	    )
509	}
