511	/// Acquire an exclusive sidecar `.lock` file around a write operation, with a
512	/// timeout so a stranded lock (crashed tomlctl, OS-mandatory Windows lock,
513	/// heavy contention) produces a clear error instead of hanging forever.
514	///
515	/// Timeout default is 30 seconds; override with the `TOMLCTL_LOCK_TIMEOUT`
516	/// env var (integer seconds). On the first observed contention the function
517	/// emits a one-shot stderr note so a human watching the terminal knows *why*
518	/// we're paused. The retry delay carries ±20% jitter (deterministic counter
519	/// hash, no external RNG) to avoid lockstep retries between competing
520	/// processes.
521	fn with_exclusive_lock<R>(path: &Path, f: impl FnOnce() -> Result<R>) -> Result<R> {
522	    use fs4::fs_std::FileExt;
523	    use std::time::{Duration, Instant};
524	
525	    let lock_path = path.with_extension(match path.extension().and_then(|s| s.to_str()) {
526	        Some(ext) => format!("{}.lock", ext),
527	        None => "lock".to_string(),
528	    });
529	    let lock_file = std::fs::OpenOptions::new()
530	        .create(true)
531	        .truncate(false)
532	        .read(true)
533	        .write(true)
534	        .open(&lock_path)
535	        .with_context(|| format!("opening lock file {}", lock_path.display()))?;
536	
537	    let timeout_secs: u64 = std::env::var("TOMLCTL_LOCK_TIMEOUT")
538	        .ok()
539	        .and_then(|s| s.parse::<u64>().ok())
540	        .unwrap_or(30);
541	    let timeout = Duration::from_secs(timeout_secs);
542	    let base_delay_ms: u64 = 500;
543	    let start = Instant::now();
544	    let mut announced = false;
545	    let mut attempt: u64 = 0;
546	    loop {
547	        match lock_file.try_lock_exclusive() {
548	            Ok(true) => break,
549	            Ok(false) => {
550	                if !announced {
551	                    eprintln!(
552	                        "tomlctl: waiting for exclusive lock on {} …",
553	                        lock_path.display()
554	                    );
555	                    announced = true;
556	                }
557	                if start.elapsed() >= timeout {
558	                    bail!(
559	                        "lock held on {} for {} seconds — another tomlctl process may be hanging. If no tomlctl process is running, check for stale lock and delete {} manually.",
560	                        lock_path.display(),
561	                        timeout_secs,
562	                        lock_path.display()
563	                    );
564	                }
565	                // ±20% jitter via a small counter hash (no RNG needed).
566	                // Hash maps attempt into [-20, 20] percent of base_delay_ms.
567	                let h = attempt
568	                    .wrapping_mul(0x9E37_79B9_7F4A_7C15)
569	                    .wrapping_add(0xD1B5_4A32_D192_ED03);
570	                let jitter_pct = (h % 41) as i64 - 20; // -20..=20
571	                let delta_ms = (base_delay_ms as i64) * jitter_pct / 100;
572	                let delay_ms = (base_delay_ms as i64 + delta_ms).max(1) as u64;
573	                std::thread::sleep(Duration::from_millis(delay_ms));
574	                attempt = attempt.wrapping_add(1);
575	            }
576	            Err(e) => {
577	                return Err(anyhow!(e)).with_context(|| {
578	                    format!("acquiring exclusive lock on {}", lock_path.display())
579	                });
580	            }
581	        }
582	    }
583	
584	    let result = f();
585	    // Drop releases the lock automatically; no explicit unlock needed.
586	    let _ = lock_file;
587	    result
588	}
