590	/// Refuse to write to files outside the current repo's `.claude/` directory
591	/// unless `--allow-outside` was passed on this invocation. Protects against
592	/// agent-influenced `artifacts.*` paths pointing at e.g. credential files.
593	///
594	/// Resolution strategy:
595	///   1. Canonicalise the target (parent if file doesn't exist yet).
596	///   2. Find the git top-level via `git rev-parse --show-toplevel`.
597	///      Fall back to CWD if git is missing or we're not inside a repo.
598	///   3. Assert canonical target lies under `<root>/.claude/`.
599	fn guard_write_path(file: &Path, allow_outside: bool) -> Result<()> {
600	    let canonical = canonicalize_for_write(file).with_context(|| {
601	        format!("canonicalising write target {}", file.display())
602	    })?;
603	
604	    let root = repo_or_cwd_root()?;
605	    let claude_dir = root.join(".claude");
606	    // Canonicalise the allowed root too so the prefix comparison is apples-to-apples
607	    // (on Windows, canonicalize yields extended-length `\\?\` paths).
608	    let claude_canonical = match claude_dir.canonicalize() {
609	        Ok(p) => p,
610	        Err(_) => claude_dir.clone(),
611	    };
612	
613	    if canonical.starts_with(&claude_canonical) {
614	        return Ok(());
615	    }
616	
617	    if allow_outside {
618	        eprintln!(
619	            "tomlctl: warning: writing outside .claude/ (path resolves to {}) — proceeding because --allow-outside was set",
620	            canonical.display()
621	        );
622	        return Ok(());
623	    }
624	
625	    bail!(
626	        "refusing to write outside .claude/ (path resolves to {}); pass --allow-outside to override",
627	        canonical.display()
628	    )
629	}
