631	/// Canonicalise a write target. If the file doesn't exist yet, canonicalise the
632	/// parent directory and re-attach the final component. Bails if neither the
633	/// file nor its parent directory exists.
634	///
635	/// R4: additionally rejects any `..` (`Component::ParentDir`) component in the
636	/// joined path. The parent canonicalises via `canonicalize()` which resolves
637	/// any embedded `..`, so a `ParentDir` in the joined result can only come from
638	/// the file-name component itself — a value like `../escape` is obviously
639	/// malicious and gets refused here even though it didn't appear after the
640	/// canonical parent prefix.
641	fn canonicalize_for_write(file: &Path) -> Result<PathBuf> {
642	    if let Ok(c) = file.canonicalize() {
643	        return Ok(c);
644	    }
645	    let parent = file
646	        .parent()
647	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
648	        .unwrap_or(Path::new("."));
649	    let parent_canonical = parent
650	        .canonicalize()
651	        .with_context(|| format!("parent directory {} not found", parent.display()))?;
652	    let name = file
653	        .file_name()
654	        .ok_or_else(|| anyhow!("write target `{}` has no file name", file.display()))?;
655	    let joined = parent_canonical.join(name);
656	    // Reject ParentDir / RootDir components past the canonical parent prefix.
657	    // Canonicalize() normalised the prefix, so anything in `joined.components()`
658	    // after the prefix that is a `..` came from the file-name piece — refuse.
659	    let prefix_len = parent_canonical.components().count();
660	    for comp in joined.components().skip(prefix_len) {
661	        match comp {
662	            std::path::Component::ParentDir | std::path::Component::RootDir => {
663	                bail!(
664	                    "write target `{}` contains a disallowed `..` or absolute root component after canonicalisation",
665	                    file.display()
666	                );
667	            }
668	            _ => {}
669	        }
670	    }
671	    Ok(joined)
672	}
