674	/// Return the containment anchor used by `guard_write_path`.
675	///
676	/// Resolution order:
677	///   1. `TOMLCTL_ROOT` env var, if set. Canonicalised; errors if the directory
678	///      does not exist. Intended for tests, chroots, and unusual layouts where
679	///      neither the git top-level nor the CWD is the right anchor.
680	///   2. `git rev-parse --show-toplevel` output, canonicalised.
681	///   3. Current working directory, canonicalised.
682	fn repo_or_cwd_root() -> Result<PathBuf> {
683	    if let Ok(env_root) = std::env::var("TOMLCTL_ROOT")
684	        && !env_root.is_empty()
685	    {
686	        let p = PathBuf::from(&env_root);
687	        return p.canonicalize().with_context(|| {
688	            format!("canonicalising TOMLCTL_ROOT={}", env_root)
689	        });
690	    }
691	    let cwd = std::env::current_dir().context("reading current working directory")?;
692	    match std::process::Command::new("git")
693	        .args(["rev-parse", "--show-toplevel"])
694	        .output()
695	    {
696	        Ok(out) if out.status.success() => {
697	            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
698	            if s.is_empty() {
699	                Ok(cwd)
700	            } else {
701	                let p = PathBuf::from(s);
702	                Ok(p.canonicalize().unwrap_or(p))
703	            }
704	        }
705	        _ => Ok(cwd.canonicalize().unwrap_or(cwd)),
706	    }
707	}
