709	/// Write the TOML document and (unless suppressed) also write the `<file>.sha256`
710	/// sidecar. The sidecar is hashed from the bytes that actually landed on disk
711	/// after the atomic rename, so the digest always reflects the serialiser's
712	/// output. Failure to write the sidecar is reported as a stderr warning but
713	/// does not fail the outer write — the primary data is already durable.
714	fn write_toml_with_sidecar(
715	    path: &Path,
716	    value: &TomlValue,
717	    integrity: IntegrityOpts,
718	) -> Result<()> {
719	    write_toml(path, value)?;
720	    if integrity.write_sidecar
721	        && let Err(e) = write_integrity_sidecar(path)
722	    {
723	        if integrity.strict {
724	            return Err(e).with_context(|| {
725	                format!(
726	                    "wrote {} but failed to refresh integrity sidecar (--strict-integrity was set, so this is a hard error)",
727	                    path.display()
728	                )
729	            });
730	        }
731	        eprintln!(
732	            "tomlctl: warning: wrote {} but failed to refresh integrity sidecar: {:#}",
733	            path.display(),
734	            e
735	        );
736	    }
737	    Ok(())
738	}
