740	fn write_toml(path: &Path, value: &TomlValue) -> Result<()> {
741	    let serialized = toml::to_string_pretty(value).context("serialising TOML")?;
742	    atomic_write(path, serialized.as_bytes())
743	}
744	
745	/// Atomic-replace pattern: write `bytes` to a tempfile in the same directory as
746	/// `path`, `sync_all()` to flush to disk, then `persist()` to rename into place.
747	/// The `sync_all` call is load-bearing — without it, a crash between rename and
748	/// fsync can leave the target empty on some filesystems. See the tempfile crate
749	/// docs (`/stebalien/tempfile`) for the canonical pattern.
750	fn atomic_write(path: &Path, bytes: &[u8]) -> Result<()> {
751	    let parent = path
752	        .parent()
753	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
754	        .unwrap_or(Path::new("."));
755	    let mut tmp = tempfile::NamedTempFile::new_in(parent)
756	        .with_context(|| format!("creating temp file in {}", parent.display()))?;
757	    tmp.as_file_mut()
758	        .write_all(bytes)
759	        .with_context(|| format!("writing temp file for {}", path.display()))?;
760	    tmp.as_file()
761	        .sync_all()
762	        .with_context(|| format!("fsync temp file for {}", path.display()))?;
763	    tmp.persist(path)
764	        .map_err(|e| anyhow!("atomic rename to {} failed: {}", path.display(), e.error))?;
765	    Ok(())
766	}
