768	/// Return the canonical sidecar path for `file`: `<file>.sha256`.
769	fn sidecar_path(file: &Path) -> PathBuf {
770	    let mut s = file.as_os_str().to_os_string();
771	    s.push(".sha256");
772	    PathBuf::from(s)
773	}
