775	/// Lowercase hex encoding of a byte slice. Replaces the `{:x}` formatter for
776	/// digest outputs, which stopped implementing `LowerHex` in sha2 0.11.
777	fn hex_lower(bytes: &[u8]) -> String {
778	    use std::fmt::Write;
779	    let mut s = String::with_capacity(bytes.len() * 2);
780	    for b in bytes {
781	        let _ = write!(s, "{:02x}", b);
782	    }
783	    s
784	}
