786	/// Compute the SHA-256 hex digest of a file's current bytes.
787	fn sha256_hex_of_file(file: &Path) -> Result<String> {
788	    let bytes =
789	        fs::read(file).with_context(|| format!("reading {} for hashing", file.display()))?;
790	    Ok(hex_lower(&Sha256::digest(&bytes)))
791	}
