793	/// Write the sidecar for `file`. Format mirrors `sha256sum` output exactly:
794	/// `<lowercase-hex-64>  <basename>\n`.
795	///
796	/// The sidecar is written via a tempfile in the same directory, then renamed,
797	/// so a concurrent reader never sees a half-written sidecar.
798	fn write_integrity_sidecar(file: &Path) -> Result<()> {
799	    let hex = sha256_hex_of_file(file)?;

800	    let sidecar = sidecar_path(file);
801	    let basename = file
802	        .file_name()
803	        .ok_or_else(|| anyhow!("target `{}` has no file name", file.display()))?
804	        .to_string_lossy()
805	        .into_owned();
806	    let contents = format!("{}  {}\n", hex, basename);
807	    atomic_write(&sidecar, contents.as_bytes())
808	}
