810	/// If `--verify-integrity` was set, verify the target against its sidecar.
811	/// Errors if the sidecar is missing or the digest disagrees.
812	fn maybe_verify_integrity(file: &Path, integrity: IntegrityOpts) -> Result<()> {
813	    if !integrity.verify_on_read {
814	        return Ok(());
815	    }
816	    verify_integrity(file)
