819	fn verify_integrity(file: &Path) -> Result<()> {
820	    let sidecar = sidecar_path(file);
821	    if !sidecar.exists() {
822	        bail!(
823	            "integrity check failed: sidecar {} is missing (expected `<hex>  <basename>` format — rewrite the file without --no-write-integrity to regenerate)",
824	            sidecar.display()
825	        );
826	    }
827	    let sidecar_text = fs::read_to_string(&sidecar)
828	        .with_context(|| format!("reading sidecar {}", sidecar.display()))?;
829	    let expected = sidecar_text.split_whitespace().next().ok_or_else(|| {
830	        anyhow!(
831	            "integrity sidecar {} is empty or malformed",
832	            sidecar.display()
833	        )
834	    })?;
835	    if expected.len() != 64 || !expected.chars().all(|c| c.is_ascii_hexdigit()) {
836	        bail!(
837	            "integrity sidecar {} does not contain a 64-hex-char digest (got `{}`)",
838	            sidecar.display(),
839	            expected
840	        );
841	    }
842	    let actual = sha256_hex_of_file(file)?;
843	    if !expected.eq_ignore_ascii_case(&actual) {
844	        bail!(
845	            "integrity check failed for {}: expected {}, actual {} (sidecar: {})",
846	            file.display(),
847	            expected,
848	            actual,
849	            sidecar.display()
850	        );
851	    }
852	    Ok(())
853	}
