906	                .with_context(|| format!("`{}` is not a valid float", input))?,
907	        )),
908	        ScalarType::Bool => Ok(TomlValue::Boolean(
909	            input
910	                .parse::<bool>()
911	                .with_context(|| format!("`{}` is not a valid bool", input))?,
912	        )),
913	        ScalarType::Date | ScalarType::Datetime => {
