922	fn infer_type(s: &str) -> ScalarType {
923	    if s == "true" || s == "false" {
924	        ScalarType::Bool
925	    } else if looks_like_date(s) {
926	        ScalarType::Date
927	    } else if s.parse::<i64>().is_ok() {
928	        ScalarType::Int
929	    } else {
930	        ScalarType::Str
931	    }
932	}
933	
934	fn looks_like_date(s: &str) -> bool {
935	    let b = s.as_bytes();
936	    b.len() == 10
937	        && b[4] == b'-'
938	        && b[7] == b'-'
939	        && b[..4].iter().all(|c| c.is_ascii_digit())
940	        && b[5..7].iter().all(|c| c.is_ascii_digit())
941	        && b[8..10].iter().all(|c| c.is_ascii_digit())
942	}
