944	fn toml_to_json(v: &TomlValue) -> JsonValue {
945	    match v {
946	        TomlValue::String(s) => JsonValue::String(s.clone()),
947	        TomlValue::Integer(i) => JsonValue::from(*i),
948	        TomlValue::Float(f) => serde_json::Number::from_f64(*f)
949	            .map(JsonValue::Number)
950	            .unwrap_or(JsonValue::Null),
951	        TomlValue::Boolean(b) => JsonValue::Bool(*b),
952	        TomlValue::Datetime(dt) => JsonValue::String(dt.to_string()),
953	        TomlValue::Array(a) => JsonValue::Array(a.iter().map(toml_to_json).collect()),
954	        TomlValue::Table(t) => {
955	            let mut m = serde_json::Map::new();
956	            for (k, v) in t.iter() {
957	                m.insert(k.clone(), toml_to_json(v));
958	            }
959	            JsonValue::Object(m)
960	        }
961	    }
962	}
