964	fn json_to_toml(v: &JsonValue) -> Result<TomlValue> {
965	    match v {
966	        JsonValue::Null => bail!("TOML has no null type"),
967	        JsonValue::Bool(b) => Ok(TomlValue::Boolean(*b)),
968	        JsonValue::Number(n) => {
969	            if let Some(i) = n.as_i64() {
970	                Ok(TomlValue::Integer(i))
971	            } else if let Some(f) = n.as_f64() {
972	                Ok(TomlValue::Float(f))
973	            } else {
974	                bail!("number `{}` is not representable in TOML", n)
975	            }
976	        }
977	        JsonValue::String(s) => Ok(TomlValue::String(s.clone())),
978	        JsonValue::Array(a) => {
979	            let items: Result<Vec<_>> = a.iter().map(json_to_toml).collect();
980	            Ok(TomlValue::Array(items?))
981	        }
982	        JsonValue::Object(m) => {
983	            let mut t = toml::Table::new();
984	            for (k, v) in m.iter() {
985	                t.insert(k.clone(), json_to_toml(v)?);
986	            }
987	            Ok(TomlValue::Table(t))
988	        }
989	    }
990	}
