1014	/// Bundle of optional per-field filters for `items list`. All populated filters
1015	/// combine via logical AND; unset filters are no-ops.
1016	#[derive(Clone, Copy, Default)]
1017	struct ListFilters<'a> {
1018	    status: Option<&'a str>,
1019	    category: Option<&'a str>,
1020	    newer_than: Option<&'a toml::value::Datetime>,
1021	    file_filter: Option<&'a str>,
1022	}
