1024	fn items_list(doc: &TomlValue, filters: ListFilters<'_>) -> Result<Vec<JsonValue>> {
1025	    let items = items_array(doc, "items")?;
1026	    let mut out = Vec::new();
1027	    for item in items {
1028	        let tbl = match item.as_table() {
1029	            Some(t) => t,
1030	            None => continue,
1031	        };
1032	        if let Some(want) = filters.status {
1033	            let cur = tbl.get("status").and_then(|v| v.as_str()).unwrap_or("");
1034	            if cur != want {
1035	                continue;
1036	            }
1037	        }
1038	        if let Some(want) = filters.category {
1039	            let cur = tbl.get("category").and_then(|v| v.as_str()).unwrap_or("");
1040	            if cur != want {
1041	                continue;
1042	            }
1043	        }
1044	        if let Some(want) = filters.file_filter {
1045	            let cur = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
1046	            if cur != want {
1047	                continue;
1048	            }
1049	        }
1050	        if let Some(threshold) = filters.newer_than {
1051	            let ff = match tbl.get("first_flagged").and_then(|v| v.as_datetime()) {
1052	                Some(d) => d,
1053	                None => continue,
1054	            };
1055	            if !datetime_gt(ff, threshold) {
1056	                continue;
1057	            }
1058	        }
1059	        out.push(toml_to_json(item));
1060	    }
1061	    Ok(out)
1062	}
