1182	fn apply_single_op(doc: &mut TomlValue, op: &JsonValue, array_name: &str) -> Result<()> {
1183	    let obj = op
1184	        .as_object()
1185	        .ok_or_else(|| anyhow!("op must be a JSON object"))?;
1186	    let op_name = obj
1187	        .get("op")
1188	        .and_then(|v| v.as_str())
1189	        .ok_or_else(|| anyhow!("op missing `op` field"))?;
1190	    match op_name {
1191	        "add" => {
1192	            let json = obj
1193	                .get("json")
1194	                .ok_or_else(|| anyhow!("add op missing `json` field"))?;
1195	            items_add_value_to(doc, json, array_name)
1196	        }
1197	        "update" => {
1198	            let id = obj
1199	                .get("id")

1200	                .and_then(|v| v.as_str())
1201	                .ok_or_else(|| anyhow!("update op missing `id` field"))?;
1202	            let json = obj
1203	                .get("json")
1204	                .ok_or_else(|| anyhow!("update op missing `json` field"))?;
1205	            let unset: Vec<String> = match obj.get("unset") {
1206	                None | Some(JsonValue::Null) => Vec::new(),
1207	                Some(JsonValue::Array(a)) => {
1208	                    let mut out = Vec::with_capacity(a.len());
1209	                    for entry in a {
1210	                        match entry {
1211	                            JsonValue::String(s) => out.push(s.clone()),
1212	                            other => bail!(
1213	                                "update op `unset` must be an array of strings, got element `{}`",
1214	                                other
1215	                            ),
1216	                        }
1217	                    }
1218	                    out
1219	                }
1220	                Some(other) => bail!(
1221	                    "update op `unset` must be a JSON array of strings, got `{}`",
1222	                    other
1223	                ),
1224	            };
1225	            // update/remove only operate on the default `[[items]]` array;
1226	            // non-default `--array` only threads through `add` today.
1227	            let _ = array_name;
1228	            items_update_value(doc, id, json, &unset)
1229	        }
1230	        "remove" => {
1231	            let id = obj
1232	                .get("id")
1233	                .and_then(|v| v.as_str())
1234	                .ok_or_else(|| anyhow!("remove op missing `id` field"))?;
1235	            items_remove(doc, id)
1236	        }
1237	        other => bail!("unknown op `{}`", other),
1238	    }
1239	}
