1298	fn find_duplicates_tier_a(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1299	    // Group under two key-spaces:
1300	    //   by (file, symbol) when symbol is non-empty
1301	    //   by (file, summary) otherwise
1302	    // An item appears in exactly one group (either symbol-keyed or summary-keyed).
1303	    let mut by_symbol: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1304	    let mut by_summary: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1305	    for (i, item) in items.iter().enumerate() {
1306	        let tbl = match item.as_table() {
1307	            Some(t) => t,
1308	            None => continue,
1309	        };
1310	        let file = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
1311	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1312	        if !symbol.is_empty() {
1313	            by_symbol
1314	                .entry((file.to_string(), symbol.to_string()))
1315	                .or_default()
1316	                .push(i);
1317	        } else {
1318	            let summary = tbl.get("summary").and_then(|v| v.as_str()).unwrap_or("");
1319	            by_summary
1320	                .entry((file.to_string(), summary.to_string()))
1321	                .or_default()
1322	                .push(i);
1323	        }
1324	    }
1325	    let mut out = Vec::new();
1326	    for ((file, symbol), idxs) in &by_symbol {
1327	        if idxs.len() < 2 {
1328	            continue;
1329	        }
1330	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1331	        out.push(dup_group_json(
1332	            "A",
1333	            &format!("file={} symbol={}", file, symbol),
1334	            &refs,
1335	        ));
1336	    }
1337	    for ((file, summary), idxs) in &by_summary {
1338	        if idxs.len() < 2 {
1339	            continue;
1340	        }
1341	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1342	        out.push(dup_group_json(
1343	            "A",
1344	            &format!("file={} summary={}", file, summary),
1345	            &refs,
1346	        ));
1347	    }
1348	    Ok(out)
1349	}
