1351	fn find_duplicates_tier_b(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1352	    let mut groups: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1353	    for (i, item) in items.iter().enumerate() {
1354	        let tbl = match item.as_table() {
1355	            Some(t) => t,
1356	            None => continue,
1357	        };
1358	        let file = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
1359	        let summary = tbl.get("summary").and_then(|v| v.as_str()).unwrap_or("");
1360	        let severity = tbl.get("severity").and_then(|v| v.as_str()).unwrap_or("");
1361	        let category = tbl.get("category").and_then(|v| v.as_str()).unwrap_or("");
1362	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1363	        let canonical = format!(
1364	            "{}|{}|{}|{}|{}",
1365	            file, summary, severity, category, symbol
1366	        );
1367	        let full = hex_lower(&Sha256::digest(canonical.as_bytes()));
1368	        let short = full[..16].to_string();
1369	        let basename = Path::new(file)
1370	            .file_name()
1371	            .map(|s| s.to_string_lossy().into_owned())
1372	            .unwrap_or_else(|| file.to_string());
1373	        groups.entry((short, basename)).or_default().push(i);
1374	    }
1375	    let mut out = Vec::new();
1376	    for ((fingerprint, basename), idxs) in &groups {
1377	        if idxs.len() < 2 {
1378	            continue;
1379	        }
1380	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1381	        out.push(dup_group_json(
1382	            "B",
1383	            &format!(
1384	                "suggestion fingerprint={} basename={}",
1385	                fingerprint, basename
1386	            ),
1387	            &refs,
1388	        ));
1389	    }
1390	    Ok(out)
1391	}
