1393	fn find_duplicates_tier_c(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1394	    // Candidates: items with empty/missing symbol AND line > 0.
1395	    #[derive(Clone)]
1396	    struct Candidate {
1397	        idx: usize,
1398	        file: String,
1399	        line: i64,
1400	    }
1401	    let mut by_file: HashMap<String, Vec<Candidate>> = HashMap::new();
1402	    for (i, item) in items.iter().enumerate() {
1403	        let tbl = match item.as_table() {
1404	            Some(t) => t,
1405	            None => continue,
1406	        };
1407	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1408	        if !symbol.is_empty() {
1409	            continue;
1410	        }
1411	        let line = tbl.get("line").and_then(|v| v.as_integer()).unwrap_or(0);
1412	        if line <= 0 {
1413	            continue;
1414	        }
1415	        let file = tbl
1416	            .get("file")
1417	            .and_then(|v| v.as_str())
1418	            .unwrap_or("")
1419	            .to_string();
1420	        by_file.entry(file.clone()).or_default().push(Candidate {
1421	            idx: i,
1422	            file,
1423	            line,
1424	        });
1425	    }
1426	
1427	    let mut out = Vec::new();
1428	    // Deterministic order: sort file keys.
1429	    let mut files: Vec<&String> = by_file.keys().collect();
1430	    files.sort();
1431	    for file in files {
1432	        let cands = &by_file[file];
1433	        // Sort by line then idx so sweep is deterministic.
1434	        let mut sorted: Vec<Candidate> = cands.clone();
1435	        sorted.sort_by(|a, b| a.line.cmp(&b.line).then(a.idx.cmp(&b.idx)));
1436	        let n = sorted.len();
1437	        let mut i = 0;
1438	        while i < n {
1439	            // Greedy: start a group at sorted[i], extend while every pair in
1440	            // the growing group satisfies |line_a - line_b| <= 10. Because
1441	            // items are sorted by line, the tightest constraint is between
1442	            // the group's min-line (sorted[i]) and the candidate's line.
1443	            let mut j = i + 1;
1444	            while j < n && sorted[j].line - sorted[i].line <= 10 {
1445	                j += 1;
1446	            }
1447	            if j - i >= 2 {
1448	                let refs: Vec<&TomlValue> = sorted[i..j].iter().map(|c| &items[c.idx]).collect();
1449	                out.push(dup_group_json(
1450	                    "C",
1451	                    &format!(
1452	                        "file={} line_window=[{}..{}]",
1453	                        sorted[i].file, sorted[i].line, sorted[j - 1].line
1454	                    ),
1455	                    &refs,
1456	                ));
1457	                i = j;
1458	            } else {
1459	                i += 1;
1460	            }
1461	        }
1462	    }
1463	    Ok(out)
1464	}
