1468	fn items_orphans(doc: &TomlValue) -> Result<Vec<JsonValue>> {
1469	    let items = match items_array(doc, "items") {
1470	        Ok(a) => a,
1471	        Err(_) => return Ok(Vec::new()),
1472	    };
1473	
1474	    // Build set of known IDs for dangling-dep check.
1475	    let mut known_ids: HashSet<String> = HashSet::new();
1476	    for item in items {
1477	        if let Some(id) = item_id(item) {
1478	            known_ids.insert(id.to_string());
1479	        }
1480	    }
1481	
1482	    let root = repo_or_cwd_root()?;
1483	
1484	    let mut out = Vec::new();
1485	    for item in items {
1486	        let tbl = match item.as_table() {
1487	            Some(t) => t,
1488	            None => continue,
1489	        };
1490	        let id = tbl.get("id").and_then(|v| v.as_str()).unwrap_or("");
1491	        let file = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
1492	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1493	
1494	        // missing-file / symbol-missing classes (mutually exclusive: the first
1495	        // failing check wins).
1496	        if !file.is_empty() {
1497	            let resolved = resolve_relative_to_root(&root, file);
1498	            if !resolved.exists() {
1499	                let mut obj = serde_json::Map::new();
1500	                obj.insert("id".into(), JsonValue::String(id.into()));
1501	                obj.insert("class".into(), JsonValue::String("missing-file".into()));
1502	                obj.insert("file".into(), JsonValue::String(file.into()));
1503	                out.push(JsonValue::Object(obj));
1504	            } else if !symbol.is_empty() {
1505	                let contents = fs::read_to_string(&resolved).unwrap_or_default();
1506	                if !contents.contains(symbol) {
1507	                    let mut obj = serde_json::Map::new();
1508	                    obj.insert("id".into(), JsonValue::String(id.into()));
1509	                    obj.insert("class".into(), JsonValue::String("symbol-missing".into()));
1510	                    obj.insert("file".into(), JsonValue::String(file.into()));
1511	                    obj.insert("symbol".into(), JsonValue::String(symbol.into()));
1512	                    out.push(JsonValue::Object(obj));
1513	                }
1514	            }
1515	        }
1516	
1517	        // dangling-dep class (independent of the file/symbol axis; an item can
1518	        // be orphaned in both ways and will surface twice).
1519	        if let Some(deps) = tbl.get("depends_on").and_then(|v| v.as_array()) {
1520	            let mut missing: Vec<String> = Vec::new();
1521	            for dep in deps {
1522	                if let Some(d) = dep.as_str()
1523	                    && !known_ids.contains(d)
1524	                {
1525	                    missing.push(d.to_string());
1526	                }
1527	            }
1528	            if !missing.is_empty() {
1529	                let mut obj = serde_json::Map::new();
1530	                obj.insert("id".into(), JsonValue::String(id.into()));
1531	                obj.insert("class".into(), JsonValue::String("dangling-dep".into()));
1532	                obj.insert(
1533	                    "dangling_deps".into(),
1534	                    JsonValue::Array(missing.into_iter().map(JsonValue::String).collect()),
1535	                );
1536	                out.push(JsonValue::Object(obj));
1537	            }
1538	        }
1539	    }
1540	    Ok(out)
1541	}
