1556	/// Extract the byte-content between `<!-- SHARED-BLOCK:NAME START -->` and
1557	/// `<!-- SHARED-BLOCK:NAME END -->` markers. Markers themselves are NOT
1558	/// included in the hash input. Inner lines are joined by `\n` (matching awk's
1559	/// default ORS), with every content line — including the last — followed by
1560	/// `\n`. Returns None if either marker is missing.
1561	fn extract_block(contents: &str, name: &str) -> Option<Vec<u8>> {
1562	    let start = format!("<!-- SHARED-BLOCK:{} START -->", name);
1563	    let end = format!("<!-- SHARED-BLOCK:{} END -->", name);
1564	    let mut in_block = false;
1565	    let mut saw_start = false;
1566	    let mut saw_end = false;
1567	    let mut out = Vec::new();
1568	    for line in contents.split('\n') {
1569	        if line == start {
1570	            in_block = true;
1571	            saw_start = true;
1572	            continue;
1573	        }
1574	        if line == end {
1575	            in_block = false;
1576	            saw_end = true;
1577	            continue;
1578	        }
1579	        if in_block {
1580	            out.extend_from_slice(line.as_bytes());
1581	            out.push(b'\n');
1582	        }
1583	    }
1584	    if saw_start && saw_end {
1585	        Some(out)
1586	    } else {
1587	        None
1588	    }
1589	}
