1607	fn blocks_verify(files: &[PathBuf], blocks: &[String]) -> Result<BlocksReport> {
1608	    if files.is_empty() {
1609	        bail!("blocks verify: no files supplied");
1610	    }
1611	    // If no block names given, infer from the first file.
1612	    let effective_blocks: Vec<String> = if blocks.is_empty() {
1613	        let first = &files[0];
1614	        let c = fs::read_to_string(first)
1615	            .with_context(|| format!("reading {}", first.display()))?;
1616	        scan_block_names(&c)
1617	    } else {
1618	        blocks.to_vec()
1619	    };
1620	
1621	    // Preload every file once.
1622	    let mut contents_by_file: HashMap<PathBuf, String> = HashMap::new();
1623	    for f in files {
1624	        let c = fs::read_to_string(f)
1625	            .with_context(|| format!("reading {}", f.display()))?;
1626	        contents_by_file.insert(f.clone(), c);
1627	    }
1628	
1629	    let mut all_ok = true;
1630	    let mut blocks_out = Vec::new();
1631	    for name in &effective_blocks {
1632	        let mut per_file: Vec<(PathBuf, Option<String>)> = Vec::new();
1633	        for f in files {
1634	            let contents = &contents_by_file[f];
1635	            match extract_block(contents, name) {
1636	                Some(bytes) => {
1637	                    let digest = hex_lower(&Sha256::digest(&bytes));
1638	                    per_file.push((f.clone(), Some(digest)));
1639	                }
1640	                None => per_file.push((f.clone(), None)),
1641	            }
1642	        }
1643	
1644	        let mut present: Vec<&(PathBuf, Option<String>)> = per_file
1645	            .iter()
1646	            .filter(|(_, h)| h.is_some())
1647	            .collect();
1648	        let missing: Vec<JsonValue> = per_file
1649	            .iter()
1650	            .filter(|(_, h)| h.is_none())
1651	            .map(|(f, _)| JsonValue::String(path_to_string(f)))
1652	            .collect();
1653	
1654	        let mut block_obj = serde_json::Map::new();
1655	        block_obj.insert("name".into(), JsonValue::String(name.clone()));
1656	
1657	        if present.is_empty() {
1658	            all_ok = false;
1659	            block_obj.insert("ok".into(), JsonValue::Bool(false));
1660	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1661	            blocks_out.push(JsonValue::Object(block_obj));
1662	            continue;
1663	        }
1664	
1665	        // Sort present by file path for deterministic output.
1666	        present.sort_by(|a, b| a.0.cmp(&b.0));
1667	        let first_hash = present[0].1.as_ref().unwrap().clone();
1668	        let drift = present
1669	            .iter()
1670	            .any(|(_, h)| h.as_ref().unwrap() != &first_hash);
1671	
1672	        if drift || !missing.is_empty() {
1673	            all_ok = false;
1674	        }
1675	
1676	        if drift {
1677	            block_obj.insert("ok".into(), JsonValue::Bool(false));
1678	            let drift_arr: Vec<JsonValue> = present
1679	                .iter()
1680	                .map(|(f, h)| {
1681	                    let mut o = serde_json::Map::new();
1682	                    o.insert("file".into(), JsonValue::String(path_to_string(f)));
1683	                    o.insert("hash".into(), JsonValue::String(h.clone().unwrap()));
1684	                    JsonValue::Object(o)
1685	                })
1686	                .collect();
1687	            block_obj.insert("drift".into(), JsonValue::Array(drift_arr));
1688	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1689	        } else {
1690	            let files_arr: Vec<JsonValue> = present
1691	                .iter()
1692	                .map(|(f, _)| JsonValue::String(path_to_string(f)))
1693	                .collect();
1694	            block_obj.insert("hash".into(), JsonValue::String(first_hash));
1695	            block_obj.insert("files".into(), JsonValue::Array(files_arr));
1696	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1697	        }
1698	        blocks_out.push(JsonValue::Object(block_obj));
1699	    }
1700	
1701	    let mut top = serde_json::Map::new();
1702	    top.insert("ok".into(), JsonValue::Bool(all_ok));
1703	    top.insert("blocks".into(), JsonValue::Array(blocks_out));
1704	    Ok(BlocksReport {
1705	        ok: all_ok,
1706	        ok_field: JsonValue::Object(top),
1707	    })
1708	}
