2025	    fn write_integrity_sidecar_roundtrip() {
2026	        let dir = tempfile::tempdir().unwrap();
2027	        let target = dir.path().join("ledger.toml");
2028	        let mut doc = led();
2029	        items_add(
2030	            &mut doc,
2031	            r#"{"id":"R5","file":"src/c.rs","line":1,"severity":"suggestion","effort":"trivial","category":"quality","summary":"baz","first_flagged":"2026-04-17","rounds":1,"status":"open"}"#,
2032	        )
2033	        .unwrap();
2034	        write_toml_with_sidecar(&target, &doc, integrity_write_only()).unwrap();
2035	
2036	        // Sidecar exists with sha256sum-style format.
2037	        let sidecar = sidecar_path(&target);
2038	        assert!(sidecar.exists(), "sidecar must be written by default");
2039	        let side = fs::read_to_string(&sidecar).unwrap();
2040	        assert!(side.ends_with("  ledger.toml\n"), "got sidecar: {side:?}");
2041	        let hex = side.split_whitespace().next().unwrap();
2042	        assert_eq!(hex.len(), 64);
2043	
2044	        // Verify succeeds.
2045	        verify_integrity(&target).unwrap();
2046	
2047	        // Flip a byte in the target; verify now errors with both digests.
2048	        let mut bytes = fs::read(&target).unwrap();
2049	        // Mutate a byte in a way that keeps the file valid TOML — replace the
2050	        // first 'R' in the item ids with 'Q'. Actually we just need any change
2051	        // for the hash to differ; integrity check doesn't reparse.
2052	        let pos = bytes.iter().position(|&b| b == b'R').unwrap();
2053	        bytes[pos] = b'Q';
2054	        fs::write(&target, &bytes).unwrap();
2055	        let err = verify_integrity(&target).unwrap_err();
2056	        let msg = format!("{err:#}");
2057	        assert!(
2058	            msg.contains("expected") && msg.contains("actual"),
2059	            "expected dual-digest message, got: {msg}"
2060	        );
2061	    }
