2676	    #[test]
2677	    fn with_exclusive_lock_contention_times_out() {
2678	        use std::sync::mpsc;
2679	        use std::thread;
2680	        use std::time::{Duration, Instant};
2681	
2682	        let _guard = env_lock();
2683	        // Short timeout so the test finishes quickly.
2684	        unsafe {
2685	            std::env::set_var("TOMLCTL_LOCK_TIMEOUT", "1");
2686	        }
2687	
2688	        let dir = tempfile::tempdir().unwrap();
2689	        let target = dir.path().join("ledger.toml");
2690	        fs::write(&target, LEDGER).unwrap();
2691	
2692	        // Thread A takes the lock and sleeps long enough for thread B to
2693	        // hit its own timeout.
2694	        let (a_ready_tx, a_ready_rx) = mpsc::channel();
2695	        let (b_done_tx, b_done_rx) = mpsc::channel();
2696	        let target_a = target.clone();
2697	        let a = thread::spawn(move || {
2698	            with_exclusive_lock(&target_a, || {
2699	                a_ready_tx.send(()).unwrap();
2700	                // Hold the lock longer than B's timeout budget.
2701	                thread::sleep(Duration::from_millis(3_000));
2702	                Ok(())
2703	            })
2704	            .unwrap();
2705	        });
2706	        a_ready_rx.recv().unwrap();
2707	
2708	        let target_b = target.clone();
2709	        let b = thread::spawn(move || {
2710	            let started = Instant::now();
2711	            let res: Result<()> = with_exclusive_lock(&target_b, || Ok(()));
2712	            b_done_tx.send(started.elapsed()).unwrap();
2713	            res
2714	        });
2715	
2716	        let b_elapsed = b_done_rx.recv().unwrap();
2717	        let b_res = b.join().unwrap();
2718	        a.join().unwrap();
2719	
2720	        unsafe {
2721	            std::env::remove_var("TOMLCTL_LOCK_TIMEOUT");
2722	        }
2723	
2724	        assert!(b_res.is_err(), "thread B must time out under contention");
2725	        // With a 1-second timeout we should be done well under 3s (the hold).
2726	        assert!(
2727	            b_elapsed < Duration::from_millis(2_500),
2728	            "B took {:?}, expected < 2.5s under a 1s lock timeout",
2729	            b_elapsed
2730	        );
2731	    }
