2777	    fn env_lock() -> std::sync::MutexGuard<'static, ()> {
2778	        use std::sync::{Mutex, OnceLock};
2779	        static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
2780	        LOCK.get_or_init(|| Mutex::new(())).lock().unwrap_or_else(|p| p.into_inner())
